  console.log(`\n== ${title} count=${related.length} ==`);
  for (const d of related) {
    const pos = d.file.getLineAndCharacterOfPosition(d.start ?? 0);
    const msg = ts.flattenDiagnosticMessageText(d.messageText, '\n');
